90	 * than from measuring a tile the browser has drawn. That is what keeps the
91	 * layout a plain function of the map, testable without a browser, and it is why
92	 * a tile's box and the box the layout reserved for it are always the same box.
93	 */
94	export interface LayoutTile {
95	  readonly id: string;
96	  readonly height: number;
97	}
