111	 *   them. This is what makes the map readable left to right instead of a ball
112	 *   of string.
113	 * - **RIGHT** — causes on the left, effects on the right, which is the order an
114	 *   English sentence puts them in.
115	 * - **NETWORK_SIMPLEX** — how tiles are placed up and down within a column. It
116	 *   pulls each tile level with the tiles it is joined to, so an arrow is
117	 *   horizontal wherever it can be.
118	 * - **semiInteractive** — when a tile already has a position, keep its place in
119	 *   the order of its column rather than sorting it afresh. This is what stops
120	 *   the map rearranging itself as it grows.
121	 * - **120 between layers** — the gap between columns, which is also the length
122	 *   of the shortest wire, and so how much room a wire has to say something.
123	 * - **48 within a layer** — the gap between two tiles in the same column. Not
124	 *   settled anywhere; chosen so the note a tile opens when you look at a belief
125	 *   chip has somewhere to go.
126	 */
127	export const LAYOUT_OPTIONS: LayoutOptions = {
128	  "elk.algorithm": "layered",
129	  "elk.direction": "RIGHT",
130	  "elk.layered.nodePlacement.strategy": "NETWORK_SIMPLEX",
131	  "elk.layered.crossingMinimization.semiInteractive": "true",
132	  "elk.layered.spacing.nodeNodeBetweenLayers": "120",
133	  "elk.spacing.nodeNode": "48",
134	};
