148	 */
149	export function toElkGraph(
150	  tiles: readonly LayoutTile[],
151	  edges: readonly LayoutEdge[],
152	  placed: ReadonlyMap<string, Position>,
153	): ElkNode {
154	  const children: ElkNode[] = tiles.map(({ id, height }) => {
155	    const already = placed.get(id);
156	    const child: ElkNode = { id, width: TILE_WIDTH, height };
157	    if (already !== undefined) {
158	      return {
159	        ...child,
160	        x: already.x,
161	        y: already.y,
162	        layoutOptions: { "elk.position": `(${already.x},${already.y})` },
163	      };
164	    }
165	    return child;
166	  });
