178	 * The gap the layout leaves between two boxes in one column.
179	 *
180	 * The same forty-eight pixels `LAYOUT_OPTIONS` asks the engine for, written here
181	 * as a number because the rule below has to leave it too, and one gap written in
182	 * two places is two gaps waiting to disagree.
183	 */
184	export const COLUMN_GAP = Number(LAYOUT_OPTIONS["elk.spacing.nodeNode"]);
185	
186	/** Do these two boxes stand in the same column? */
187	function sameColumn(one: Placed, other: Placed): boolean {
188	  return Math.abs(one.at.x - other.at.x) < TILE_WIDTH;
189	}
190	
191	/** Do these two boxes overlap, or touch, once the column's gap is counted? */
192	function runsInto(one: Placed, other: Placed): boolean {
193	  return (
194	    sameColumn(one, other) &&
195	    one.at.y < other.at.y + other.height + COLUMN_GAP &&
196	    other.at.y < one.at.y + one.height + COLUMN_GAP
197	  );
198	}
