236	 * @param laidOut What the layout engine returned.
237	 * @param placed Where tiles already sat before it ran.
238	 * @returns Where every tile sits now.
239	 */
240	export function readPositions(
241	  laidOut: ElkNode,
242	  placed: ReadonlyMap<string, Position>,
243	): Map<string, Position> {
244	  const settled: Placed[] = [];
245	  const arriving: Placed[] = [];
246	
247	  for (const child of laidOut.children ?? []) {
248	    const height = child.height ?? 0;
249	    const pinned = placed.get(child.id);
250	    if (pinned !== undefined) {
251	      settled.push({ id: child.id, at: pinned, height });
252	    } else {
253	      arriving.push({ id: child.id, at: { x: child.x ?? 0, y: child.y ?? 0 }, height });
254	    }
255	  }
256	
257	  // The engine's own order, so the same map always settles the same way. The
258	  // identifier breaks a tie, because two boxes proposed at the same height must
259	  // not depend on which the engine happened to list first.
260	  arriving.sort((one, other) => one.at.y - other.at.y || one.id.localeCompare(other.id));
261	
262	  for (const box of arriving) {
263	    let at = box.at;
264	    // Each pass can only push the box further down, and there are finitely many
265	    // boxes below it, so this always settles.
266	    for (let pass = 0; pass <= settled.length; pass += 1) {
267	      const inTheWay = settled.find((other) => runsInto({ ...box, at }, other));
268	      if (inTheWay === undefined) {
269	        break;
270	      }
271	      at = { x: at.x, y: inTheWay.at.y + inTheWay.height + COLUMN_GAP };
272	    }
273	    settled.push({ ...box, at });
274	  }
275	
276	  return new Map(settled.map((box) => [box.id, box.at]));
277	}
