1	/**
2	 * Working out where every tile goes, on a thread that is not the one drawing
3	 * the page.
4	 *
5	 * Laying out a map of sixty tiles takes the layout engine somewhere between
6	 * fifty and a hundred and fifty milliseconds. On the thread that draws the page
7	 * that is three to nine dropped frames: the page freezes, the map stutters as it
8	 * grows, and a tool that stutters reads as a tool that is struggling. So the
9	 * work happens on a background thread, and the page carries on drawing while it
10	 * waits.
11	 *
12	 * The background thread is the layout engine's own. Its package ships the
13	 * algorithm as a script written to be run that way — ask it for a copy of that
14	 * script's address and hand the address over, and it starts the thread itself.
15	 * Writing our own wrapper thread around it, which was the first attempt, does
16	 * not work: the script checks whether it is already inside a background thread
17	 * and, finding that it is, wires itself up as that thread rather than handing
18	 * back something to call.
19	 *
20	 * Nothing on this thread ever sees a likelihood. A tile, to the layout engine,
21	 * is an identifier and a box.
22	 */
23	
24	import ELK, { type ELK as LayoutEngine } from "elkjs/lib/elk-api.js";
25	import elkWorkerAddress from "elkjs/lib/elk-worker.min.js?url";
26	import { useEffect, useMemo, useRef, useState } from "react";
27	import {
28	  type LayoutEdge,
29	  type LayoutTile,
30	  type PinnedTile,
31	  type Position,
32	  pinsFor,
33	  readPositions,
34	  toElkGraph,
35	} from "./elkGraph";
36	
37	/** Where every tile sits, and which run of the layout put it there. */
38	export interface Layout {
39	  /** Where each tile sits, by identifier. Empty until the first answer arrives. */
40	  readonly positions: ReadonlyMap<string, Position>;
41	  /**
42	   * How many layouts have finished.
43	   *
44	   * Zero means none has, and so nothing should be drawn yet. It goes up by one
45	   * each time, which is what lets the canvas tell "the map has just been laid
46	   * out for the first time" — frame the whole map — from "it has been laid out
47	   * again" — stay where the reader was.
48	   */
49	  readonly runs: number;
50	  /**
51	   * Which map these positions are for.
52	   *
53	   * It lags the map on screen by exactly as long as the layout takes, and that
54	   * matters: framing the view from positions worked out for the map *before* the
55	   * branch would frame the wrong thing, and then the right thing would arrive
56	   * underneath it.
57	   */
58	  readonly laidOutFor: string;
59	  /** What went wrong, in a sentence, if anything did. */
60	  readonly failure: string | null;
61	}
62	
63	/**
64	 * One background thread, shared by everything on the page that needs a layout.
65	 *
66	 * Started the first time it is asked for rather than when this file loads,
67	 * because a test running in a simulated page has no threads to start and should
68	 * not have one started for it.
69	 */
70	let engine: LayoutEngine | null = null;
71	
72	function layoutEngine(): LayoutEngine {
73	  engine ??= new ELK({ workerUrl: elkWorkerAddress });
74	  return engine;
75	}
76	
77	/**
78	 * How long the background thread gets before the page does the work itself.
79	 *
80	 * The background thread is the normal path and it answers in well under a tenth
81	 * of a second. But a thread that never answers leaves every tile stacked in the
82	 * top left corner with nothing on screen saying why — which is the "why did it
83	 * do that" failure in its purest form. Some browsers, and some browsers under
84	 * instrumentation, will not run the layout engine's own worker script at all.
85	 *
86	 * So after this long the page lays the map out on its own thread instead. That
87	 * costs a few dropped frames once; a map that never arrives costs everything.
88	 */
89	const THREAD_PATIENCE = 2000;
90	
91	/** What the race below hands back when the background thread has not answered. */
92	const TOO_SLOW = Symbol("the background thread has not answered");
93	
94	/**
95	 * Lay the map out on the background thread, or — if that thread does not answer
96	 * — on this one.
97	 *
98	 * The fallback is loaded only if it is needed, so the packaged app does not
99	 * carry a second copy of the layout engine unless a reader's browser makes it
100	 * necessary.
101	 */
102	async function laidOut(graph: Parameters<LayoutEngine["layout"]>[0]) {
103	  const answer = await Promise.race([
104	    layoutEngine().layout(graph),
105	    new Promise<typeof TOO_SLOW>((settle) => {
106	      setTimeout(() => settle(TOO_SLOW), THREAD_PATIENCE);
107	    }),
108	  ]);
109	  if (answer !== TOO_SLOW) {
110	    return answer;
111	  }
112	  const onThisThread = await import("elkjs/lib/elk.bundled.js");
113	  return new onThisThread.default().layout(graph);
114	}
115	
116	/** Say what went wrong in a sentence, whatever was thrown. */
117	function inWords(reason: unknown): string {
118	  return reason instanceof Error ? reason.message : "The layout engine stopped without saying why.";
119	}
120	
121	/**
122	 * Work out where every tile goes, on a background thread, and keep tiles that
